import React from 'react';
import Card from '../ui/Card';

/** Tarjeta de categoría, arrastrable para reordenar el menú. */
const CategoryCard = ({ category, isDragging, onDragStart, onDrop, onEdit, onDelete }) => (
  <Card
    draggable
    onDragStart={onDragStart}
    onDragOver={(e) => e.preventDefault()}
    onDrop={onDrop}
    style={{ cursor: 'grab', opacity: isDragging ? 0.4 : 1 }}
  >
    <div className="flex items-center gap-2.5 mb-2">
      <span className="text-[28px]">{category.icon}</span>
      <div>
        <h3 className="text-slate-200 text-base">{category.name}</h3>
        <p className="text-slate-500 text-xs">
          {category.productCount} producto{category.productCount !== 1 ? 's' : ''}
        </p>
      </div>
    </div>
    {category.description && <p className="text-slate-400 text-xs mb-3">{category.description}</p>}
    <div className="flex gap-1.5">
      <button onClick={onEdit} className="flex-1 px-2.5 py-1.5 rounded-md border-none bg-sky-400/10 text-sky-400 text-xs font-semibold cursor-pointer">
        ✏️ Editar
      </button>
      <button onClick={onDelete} className="flex-1 px-2.5 py-1.5 rounded-md border-none bg-red-500/10 text-red-500 text-xs font-semibold cursor-pointer">
        🗑️ Eliminar
      </button>
    </div>
  </Card>
);

export default CategoryCard;
